{
  "name": "@rachel_rotenberg/ai-contribution-tracker",
  "version": "1.1.0",
  "description": "Tracks AI coding sessions in OpenCode 1.x, OpenCode 2.x and OmO Native and tags git commits with Impacted by AI markers",
  "main": "index.ts",
  "types": "index.ts",
  "bin": {
    "ai-contribution-tracker": "cli.js"
  },
  "files": [
    "index.ts",
    "core.ts",
    "v1.ts",
    "v2.ts",
    "senpi.ts",
    "cli.js",
    "README.md",
    "CHANGELOG.md"
  ],
  "exports": {
    ".": {
      "import": "./index.ts",
      "default": "./index.ts"
    },
    "./senpi": {
      "import": "./senpi.ts",
      "default": "./senpi.ts"
    }
  },
  "pi": {
    "extensions": [
      "./senpi.ts"
    ]
  },
  "scripts": {
    "test": "node --test test/",
    "typecheck": "tsc -p ."
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "pi-package",
    "omo",
    "ai",
    "tracking",
    "git",
    "commits"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/YoavLax/AI-Contribution-Tracker.git"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.29",
    "@opencode/plugin": ">=2.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    }
  }
}
